  1→import { useState } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import { Card, CardContent } from "@/components/ui/card";
  5→import { Button } from "@/components/ui/button";
  6→import { Input } from "@/components/ui/input";
  7→import { Switch } from "@/components/ui/switch";
  8→import { Label } from "@/components/ui/label";
  9→import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
 10→import { toast } from "sonner";
 11→import { Copy, Mail, Check, ChevronDown, Info, RefreshCw, Loader2 } from "lucide-react";
 12→
 13→const EmailInboxCard = () => {
 14→  const { user, profile, refreshProfile } = useAuth();
 15→  const [togglingEmail, setTogglingEmail] = useState(false);
 16→  const [copied, setCopied] = useState(false);
 17→  const [howItWorksOpen, setHowItWorksOpen] = useState(false);
 18→  const [regenerating, setRegenerating] = useState(false);
 19→
 20→  const handleCopyInbox = () => {
 21→    if (profile?.inbox_email) {
 22→      navigator.clipboard.writeText(profile.inbox_email);
 23→      setCopied(true);
 24→      toast.success("Inbox email copied to clipboard.");
 25→      setTimeout(() => setCopied(false), 2000);
 26→    }
 27→  };
 28→
 29→  const handleRegenerateInbox = async () => {
 30→    if (!user) return;
 31→    setRegenerating(true);
 32→    try {
 33→      const { data, error } = await supabase.rpc("generate_user_inbox_email", { p_user_id: user.id });
 34→      if (error) throw error;
 35→      await refreshProfile();
 36→      toast.success(`Inbox regenerated: ${data}`);
 37→    } catch (e: any) {
 38→      toast.error(e.message || "Failed to regenerate inbox");
 39→    } finally {
 40→      setRegenerating(false);
 41→    }
 42→  };
 43→
 44→  const handleToggleEmail = async (checked: boolean) => {
 45→    if (!user) return;
 46→    setTogglingEmail(true);
 47→    const { error } = await supabase
 48→      .from("profiles")
 49→      .update({ email_enabled: checked })
 50→      .eq("user_id", user.id);
 51→    if (error) {
 52→      toast.error(error.message);
 53→    } else {
 54→      await refreshProfile();
 55→      toast.success(checked ? "Email enabled" : "Email disabled");
 56→    }
 57→    setTogglingEmail(false);
 58→  };
 59→
 60→  return (
 61→    <Card className="overflow-hidden">
 62→      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
 63→        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
 64→          <Mail className="h-4.5 w-4.5 text-primary" />
 65→        </div>
 66→        <div>
 67→          <h3 className="text-base font-semibold text-foreground">Email Inbox</h3>
 68→          <p className="text-xs text-muted-foreground">
 69→            Forward resumes here to auto-add them to your jobs.
 70→          </p>
 71→        </div>
 72→      </div>
 73→      <CardContent className="px-6 pt-3 pb-5 space-y-4">
 74→        {profile?.inbox_email ? (
 75→          <>
 76→            <div>
 77→              <Label className="text-xs text-muted-foreground mb-1.5 block">Your fallback inbox</Label>
 78→              <div className="flex items-center gap-2">
 79→                <Input
 80→                  value={profile.inbox_email}
 81→                  readOnly
 82→                  className="font-mono text-sm bg-accent/50"
 83→                />
 84→                <Button
 85→                  variant="outline"
 86→                  size="icon"
 87→                  onClick={handleCopyInbox}
 88→                  title="Copy"
 89→                  className="shrink-0"
 90→                >
 91→                  {copied ? (
 92→                    <Check className="h-4 w-4 text-primary" />
 93→                  ) : (
 94→                    <Copy className="h-4 w-4" />
 95→                  )}
 96→                </Button>
 97→                <Button
 98→                  variant="outline"
 99→                  size="icon"
100→                  onClick={handleRegenerateInbox}
101→                  title="Regenerate inbox email"
102→                  className="shrink-0"
103→                  disabled={regenerating}
104→                >
105→                  {regenerating ? (
106→                    <Loader2 className="h-4 w-4 animate-spin" />
107→                  ) : (
108→                    <RefreshCw className="h-4 w-4" />
109→                  )}
110→                </Button>
111→              </div>
112→            </div>
113→            <p className="text-xs text-muted-foreground">
114→              Each job also gets its own unique inbox email. Check the job detail page to copy it.
115→            </p>
116→          </>
117→        ) : (
118→          <div className="rounded-md bg-accent/50 px-3 py-3 text-sm text-muted-foreground text-center">
119→            No inbox email assigned yet.
120→          </div>
121→        )}
122→        <div className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
123→          <Label htmlFor="email-toggle" className="text-sm font-medium cursor-pointer">
124→            Email ingestion enabled
125→          </Label>
126→          <Switch
127→            id="email-toggle"
128→            checked={profile?.email_enabled ?? true}
129→            onCheckedChange={handleToggleEmail}
130→            disabled={togglingEmail}
131→          />
132→        </div>
133→
134→        {/* How it works */}
135→        <Collapsible open={howItWorksOpen} onOpenChange={setHowItWorksOpen}>
136→          <CollapsibleTrigger asChild>
137→            <Button variant="ghost" size="sm" className="w-full justify-between text-muted-foreground text-xs">
138→              <span className="flex items-center gap-1.5">
139→                <Info className="h-3.5 w-3.5" />
140→                How email ingestion works
141→              </span>
142→              <ChevronDown className={`h-3.5 w-3.5 transition-transform ${howItWorksOpen ? "rotate-180" : ""}`} />
143→            </Button>
144→          </CollapsibleTrigger>
145→          <CollapsibleContent className="pt-2">
146→            <div className="rounded-md bg-muted/50 p-3 text-xs text-muted-foreground space-y-2">
147→              <p><strong>Per-job inbox:</strong> Each job gets a unique email address. Forward resumes to it and they'll be attached directly to that job.</p>
148→              <p><strong>Fallback inbox:</strong> Your personal inbox above routes resumes to your most recent pending job.</p>
149→              <p><strong>Supported formats:</strong> PDF and DOCX attachments are automatically extracted and uploaded.</p>
150→            </div>
151→          </CollapsibleContent>
152→        </Collapsible>
153→      </CardContent>
154→    </Card>
155→  );
156→};
157→
158→export default EmailInboxCard;
