  1→import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
  2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  3→
  4→const corsHeaders = {
  5→  "Access-Control-Allow-Origin": "*",
  6→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  7→};
  8→
  9→async function authenticateAdmin(req: Request) {
 10→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 11→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 12→  const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
 13→
 14→  const authHeader = req.headers.get("Authorization");
 15→  if (!authHeader?.startsWith("Bearer ")) throw new Error("No auth");
 16→
 17→  const supabaseUser = createClient(SUPABASE_URL, anonKey, {
 18→    global: { headers: { Authorization: authHeader } },
 19→  });
 20→  const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
 21→  if (userError || !user) throw new Error("Unauthorized");
 22→  const adminUserId = user.id;
 23→
 24→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 25→
 26→  const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", adminUserId);
 27→  if (!roles?.some((r: any) => r.role === "admin")) {
 28→    throw new Error("Admin access required");
 29→  }
 30→
 31→  return { supabase, adminUserId };
 32→}
 33→
 34→serve(async (req) => {
 35→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 36→
 37→  try {
 38→    const { supabase, adminUserId } = await authenticateAdmin(req);
 39→
 40→    let body: any = null;
 41→    try {
 42→      const text = await req.text();
 43→      if (text) body = JSON.parse(text);
 44→    } catch {
 45→      // empty or invalid body — treat as list request
 46→    }
 47→
 48→    const action = body?.action;
 49→
 50→    // ─── Ban / Suspend user ───
 51→    if (action === "ban") {
 52→      const { user_id, banned } = body;
 53→      if (!user_id) throw new Error("user_id required");
 54→      if (banned) {
 55→        const { error } = await supabase.auth.admin.updateUserById(user_id, { ban_duration: "876000h" }); // ~100 years
 56→        if (error) throw error;
 57→      } else {
 58→        const { error } = await supabase.auth.admin.updateUserById(user_id, { ban_duration: "none" });
 59→        if (error) throw error;
 60→      }
 61→      return new Response(JSON.stringify({ success: true }), {
 62→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 63→      });
 64→    }
 65→
 66→    // ─── Get user activity detail ───
 67→    if (action === "activity") {
 68→      const { user_id } = body;
 69→      if (!user_id) throw new Error("user_id required");
 70→
 71→      const [usageRes, jobsRes, resumesRes, paymentsRes] = await Promise.all([
 72→        supabase.from("usage_logs").select("*").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
 73→        supabase.from("jobs").select("id, title, status, created_at").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
 74→        supabase.from("resumes").select("id, filename, status, created_at, job_id").order("created_at", { ascending: false }).limit(100),
 75→        supabase.from("payments").select("id, amount, currency, status, credits_purchased, created_at").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
 76→      ]);
 77→
 78→      // Filter resumes to only those belonging to user's jobs
 79→      const jobIds = new Set(jobsRes.data?.map((j: any) => j.id) ?? []);
 80→      const userResumes = resumesRes.data?.filter((r: any) => jobIds.has(r.job_id)) ?? [];
 81→
 82→      return new Response(JSON.stringify({
 83→        usage_logs: usageRes.data ?? [],
 84→        jobs: jobsRes.data ?? [],
 85→        resumes: userResumes,
 86→        payments: paymentsRes.data ?? [],
 87→      }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
 88→    }
 89→
 90→    // ─── GDPR data export ───
 91→    if (action === "gdpr_export") {
 92→      const { user_id } = body;
 93→      if (!user_id) throw new Error("user_id required");
 94→
 95→      const { data: authUser } = await supabase.auth.admin.getUserById(user_id);
 96→      const [profileRes, usageRes, jobsRes, paymentsRes, rolesRes] = await Promise.all([
 97→        supabase.from("profiles").select("*").eq("user_id", user_id),
 98→        supabase.from("usage_logs").select("*").eq("user_id", user_id),
 99→        supabase.from("jobs").select("*").eq("user_id", user_id),
100→        supabase.from("payments").select("*").eq("user_id", user_id),
101→        supabase.from("user_roles").select("*").eq("user_id", user_id),
102→      ]);
103→
104→      // Get resumes for user's jobs
105→      const jobIds = jobsRes.data?.map((j: any) => j.id) ?? [];
106→      let resumes: any[] = [];
107→      if (jobIds.length > 0) {
108→        const { data } = await supabase.from("resumes").select("id, filename, status, created_at, candidate_name, source").in("job_id", jobIds);
109→        resumes = data ?? [];
110→      }
111→
112→      const exportData = {
113→        exported_at: new Date().toISOString(),
114→        user: {
115→          id: authUser?.user?.id,
116→          email: authUser?.user?.email,
117→          created_at: authUser?.user?.created_at,
118→          last_sign_in_at: authUser?.user?.last_sign_in_at,
119→        },
120→        profile: profileRes.data?.[0] ?? null,
121→        roles: rolesRes.data ?? [],
122→        jobs: jobsRes.data ?? [],
123→        resumes,
124→        usage_logs: usageRes.data ?? [],
125→        payments: paymentsRes.data ?? [],
126→      };
127→
128→      return new Response(JSON.stringify(exportData), {
129→        headers: { ...corsHeaders, "Content-Type": "application/json" },
130→      });
131→    }
132→
133→    // ─── Update user profile (existing) ───
134→    if (body && body.user_id && !action) {
135→      const { user_id, credits, plan, email_enabled, bonus_credits, subscription_credits, topup_credits } = body;
136→      const updates: any = {};
137→      if (credits !== undefined) updates.credits = credits;
138→      if (plan !== undefined) updates.plan = plan;
139→      if (email_enabled !== undefined) updates.email_enabled = email_enabled;
140→      if (bonus_credits !== undefined) updates.bonus_credits = Math.max(0, bonus_credits);
141→      if (subscription_credits !== undefined) updates.subscription_credits = Math.max(0, subscription_credits);
142→      if (topup_credits !== undefined) updates.topup_credits = Math.max(0, topup_credits);
143→
144→      const { error } = await supabase.from("profiles").update(updates).eq("user_id", user_id);
145→      if (error) throw error;
146→
147→      return new Response(JSON.stringify({ success: true }), {
148→        headers: { ...corsHeaders, "Content-Type": "application/json" },
149→      });
150→    }
151→
152→    // ─── Regenerate user inbox email ───
153→    if (action === "regenerate_inbox") {
154→      const { user_id } = body;
155→      if (!user_id) throw new Error("user_id required");
156→
157→      const { data, error } = await supabase.rpc("generate_user_inbox_email", { p_user_id: user_id });
158→      if (error) throw error;
159→
160→      return new Response(JSON.stringify({ success: true, inbox_email: data }), {
161→        headers: { ...corsHeaders, "Content-Type": "application/json" },
162→      });
163→    }
164→
165→    // ─── Update platform config (email settings etc.) ───
166→    if (action === "update_config") {
167→      const allowedFields = [
168→        "email_ingestion_enabled",
169→        "outbound_email_enabled",
170→        "resend_api_key",
171→        "email_from_address",
172→        "email_from_name",
173→        "email_notify_ranking_complete",
174→        "email_notify_resume_received",
175→        "max_file_size_mb",
176→        "max_resumes_per_job",
177→        "payg_per_resume_cost",
178→        "resume_retention_days",
179→        "inbound_email_domain",
180→        "resend_inbound_webhook_secret",
181→      ];
182→
183→      const updates = body.updates || {};
184→      const setClauses: string[] = [];
185→      const values: any[] = [];
186→      let paramIdx = 1;
187→
188→      for (const [key, val] of Object.entries(updates)) {
189→        if (allowedFields.includes(key)) {
190→          setClauses.push(`${key} = $${paramIdx}`);
191→          values.push(val);
192→          paramIdx++;
193→        }
194→      }
195→
196→      if (setClauses.length === 0) throw new Error("No valid fields to update");
197→
198→      setClauses.push(`updated_at = now()`);
199→      const sql = `UPDATE platform_config SET ${setClauses.join(", ")} WHERE id = (SELECT id FROM platform_config LIMIT 1)`;
200→
201→      const { error } = await supabase.rpc("exec_sql", { query: sql, params: values }).maybeSingle();
202→
203→      // Fallback: if exec_sql RPC doesn't exist, use direct update
204→      if (error) {
205→        // Try direct update via service role (bypasses PostgREST cache for service role)
206→        const { data: configRow } = await supabase.from("platform_config").select("id").limit(1).single();
207→        if (!configRow) throw new Error("No platform_config row found");
208→
209→        const cleanUpdates: any = {};
210→        for (const [key, val] of Object.entries(updates)) {
211→          if (allowedFields.includes(key)) cleanUpdates[key] = val;
212→        }
213→
214→        const { error: updateErr } = await supabase.from("platform_config").update(cleanUpdates).eq("id", configRow.id);
215→        if (updateErr) throw updateErr;
216→      }
217→
218→      return new Response(JSON.stringify({ success: true }), {
219→        headers: { ...corsHeaders, "Content-Type": "application/json" },
220→      });
221→    }
222→
223→    // ─── Get platform config ───
224→    if (action === "get_config") {
225→      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
226→      if (error) throw error;
227→      // Mask the Resend API key for security
228→      if (data && (data as any).resend_api_key) {
229→        const key = (data as any).resend_api_key as string;
230→        (data as any).resend_api_key_masked = key.slice(0, 8) + "***" + key.slice(-4);
231→        (data as any).has_resend_key = true;
232→        delete (data as any).resend_api_key;
233→      } else {
234→        (data as any).has_resend_key = false;
235→      }
236→      // Mask the Resend inbound webhook secret for security
237→      if (data && (data as any).resend_inbound_webhook_secret) {
238→        const secret = (data as any).resend_inbound_webhook_secret as string;
239→        (data as any).resend_inbound_webhook_secret_masked = secret.slice(0, 8) + "***" + secret.slice(-4);
240→        (data as any).has_inbound_webhook_secret = true;
241→        delete (data as any).resend_inbound_webhook_secret;
242→      } else {
243→        (data as any).has_inbound_webhook_secret = false;
244→      }
245→      return new Response(JSON.stringify(data), {
246→        headers: { ...corsHeaders, "Content-Type": "application/json" },
247→      });
248→    }
249→
250→    // ─── Get email templates ───
251→    if (action === "get_templates") {
252→      const { data, error } = await supabase
253→        .from("email_templates")
254→        .select("*")
255→        .order("template_key");
256→      if (error) throw error;
257→      return new Response(JSON.stringify(data), {
258→        headers: { ...corsHeaders, "Content-Type": "application/json" },
259→      });
260→    }
261→
262→    // ─── Update email template ───
263→    if (action === "update_template") {
264→      const { template_id, subject, body_html } = body;
265→      if (!template_id) throw new Error("template_id required");
266→      const { error } = await supabase
267→        .from("email_templates")
268→        .update({ subject, body_html, updated_at: new Date().toISOString() })
269→        .eq("id", template_id);
270→      if (error) throw error;
271→      return new Response(JSON.stringify({ success: true }), {
272→        headers: { ...corsHeaders, "Content-Type": "application/json" },
273→      });
274→    }
275→
276→    // ─── List all users (default) ───
277→    const { data: authUsers } = await supabase.auth.admin.listUsers({ perPage: 1000 });
278→    const { data: profiles } = await supabase.from("profiles").select("*");
279→    const { data: userRoles } = await supabase.from("user_roles").select("*");
280→
281→    const users = authUsers?.users?.map((u: any) => {
282→      const profile = profiles?.find((p: any) => p.user_id === u.id);
283→      const role = userRoles?.find((r: any) => r.user_id === u.id);
284→      return {
285→        id: u.id,
286→        email: u.email,
287→        credits: profile?.credits ?? 0,
288→        subscription_credits: profile?.subscription_credits ?? 0,
289→        topup_credits: profile?.topup_credits ?? 0,
290→        bonus_credits: profile?.bonus_credits ?? 0,
291→        plan: profile?.plan ?? "free",
292→        role: role?.role ?? "user",
293→        inbox_email: profile?.inbox_email ?? null,
294→        email_enabled: profile?.email_enabled ?? true,
295→        created_at: u.created_at,
296→        last_sign_in_at: u.last_sign_in_at ?? null,
297→        banned_until: u.banned_until ?? null,
298→      };
299→    }) ?? [];
300→
301→    return new Response(JSON.stringify(users), {
302→      headers: { ...corsHeaders, "Content-Type": "application/json" },
303→    });
304→  } catch (err: unknown) {
305→    let msg = "Unknown error";
306→    if (err instanceof Error) msg = err.message;
307→    else if (typeof err === "object" && err !== null && "message" in err) msg = String((err as any).message);
308→    else msg = JSON.stringify(err);
309→    const status = msg === "Admin access required" ? 403 : 500;
310→    return new Response(JSON.stringify({ error: msg }), {
311→      status, headers: { ...corsHeaders, "Content-Type": "application/json" },
312→    });
313→  }
314→});
