 37→// ─── Resend health state ───
 38→interface ResendHealth {
 39→  keyValid: boolean;
 40→  domainVerified: boolean;
 41→  domainName: string;
 42→  fromEmail: string;
 43→  totalDomains: number;
 44→}
 45→
 46→// ─── Toggle row component ───
 47→function ToggleRow({
 48→  icon: Icon, label, description, checked, onToggle, disabled = false
 49→}: {
 50→  icon: React.ElementType; label: string; description: string;
 51→  checked: boolean; onToggle: (v: boolean) => void; disabled?: boolean;
 52→}) {
 53→  return (
 54→    <div className="flex items-center justify-between rounded-xl border border-border p-4 hover:bg-muted/30 transition-colors">
 55→      <div className="flex items-center gap-3">
 56→        <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
