 69→// ─── Health Alert Banner ───
 70→function HealthBanner({ health, loading, onVerify }: {
 71→  health: ResendHealth | null;
 72→  loading: boolean;
 73→  onVerify: () => void;
 74→}) {
 75→  if (loading) {
 76→    return (
 77→      <div className="rounded-lg border border-border bg-muted/30 p-4 flex items-center gap-3">
 78→        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
 79→        <span className="text-sm text-muted-foreground">Checking Resend connection...</span>
 80→      </div>
 81→    );
 82→  }
 83→
 84→  if (!health) return null;
 85→
 86→  const issues: { icon: React.ElementType; text: string; severity: "error" | "warning" }[] = [];
 87→
 88→  if (!health.keyValid) {
 89→    issues.push({ icon: XCircle, text: "API key is invalid or not configured", severity: "error" });
 90→  }
 91→  if (health.keyValid && !health.domainVerified) {
 92→    issues.push({
 93→      icon: AlertTriangle,
 94→      text: `Domain for "${health.fromEmail}" is not verified in Resend. Emails will fail.`,
 95→      severity: "warning",
 96→    });
 97→  }
 98→
 99→  if (issues.length === 0 && health.keyValid) {
100→    return (
101→      <div className="rounded-lg border border-green-200 bg-green-50 dark:border-green-900 dark:bg-green-950/50 p-4 space-y-2">
102→        <div className="flex items-center justify-between">
103→          <div className="flex items-center gap-2">
104→            <CheckCircle2 className="h-4 w-4 text-green-600" />
105→            <span className="text-sm font-medium text-green-700 dark:text-green-400">
106→              Resend Connected{health.domainName ? ` — ${health.domainName}` : ""}
107→            </span>
108→          </div>
109→          <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
110→            <RefreshCw className="h-3 w-3" /> Recheck
111→          </Button>
112→        </div>
113→        <div className="flex gap-3 text-xs text-green-600 dark:text-green-500">
114→          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> API key valid</span>
115→          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> Domain verified</span>
116→        </div>
117→      </div>
118→    );
119→  }
120→
121→  return (
122→    <div className="space-y-2">
123→      {issues.map((issue, i) => (
124→        <div
125→          key={i}
126→          className={`rounded-lg border p-3 flex items-start gap-2 ${
127→            issue.severity === "error"
128→              ? "border-destructive/50 bg-destructive/10 text-destructive"
129→              : "border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 text-amber-700 dark:text-amber-400"
130→          }`}
131→        >
132→          <issue.icon className="h-4 w-4 shrink-0 mt-0.5" />
133→          <p className="text-xs">{issue.text}</p>
134→        </div>
135→      ))}
136→      <div className="flex justify-end">
137→        <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
138→          <RefreshCw className="h-3 w-3" /> Recheck
139→        </Button>
140→      </div>
141→    </div>
142→  );
143→}
