112→/**
113→ * Fetch attachments from Resend API (inbound webhooks only include metadata).
114→ */
115→async function fetchResendAttachments(
116→  resendApiKey: string,
117→  emailId: string,
118→  maxFileSizeBytes: number,
119→): Promise<{ filename: string; content: Uint8Array }[]> {
120→  const attachmentFiles: { filename: string; content: Uint8Array }[] = [];
121→
122→  const listRes = await fetch(
123→    `https://api.resend.com/emails/receiving/${emailId}/attachments`,
124→    { headers: { Authorization: `Bearer ${resendApiKey}` } }
125→  );
126→
127→  if (!listRes.ok) {
128→    console.error("Failed to list Resend attachments:", listRes.status, await listRes.text());
129→    return attachmentFiles;
130→  }
131→
132→  const listData = await listRes.json();
133→  const attachments = listData.data || listData || [];
134→  let count = 0;
135→
136→  for (const att of (Array.isArray(attachments) ? attachments : [])) {
137→    if (count >= MAX_ATTACHMENTS_PER_EMAIL) break;
138→    if (!att.filename || !hasAllowedExtension(att.filename)) continue;
139→    if (att.size && att.size > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
140→
141→    try {
142→      const downloadRes = await fetch(att.download_url);
143→      if (!downloadRes.ok) continue;
144→      const buffer = await downloadRes.arrayBuffer();
145→      if (buffer.byteLength > Math.min(maxFileSizeBytes, MAX_ATTACHMENT_SIZE_BYTES)) continue;
146→      attachmentFiles.push({ filename: att.filename, content: new Uint8Array(buffer) });
147→      count++;
148→    } catch (e) {
149→      console.error(`Failed to download Resend attachment ${att.filename}:`, e);
150→    }
151→  }
152→
153→  return attachmentFiles;
154→}
