  6→-- 2. Replace handle_new_user() with human-readable inbox email
  7→CREATE OR REPLACE FUNCTION public.handle_new_user()
  8→  RETURNS trigger
  9→  LANGUAGE plpgsql
 10→  SECURITY DEFINER
 11→  SET search_path TO 'public'
 12→AS $function$
 13→DECLARE
 14→  raw_email text;
 15→  local_part text;
 16→  domain text;
 17→  base_inbox text;
 18→  final_inbox text;
 19→  suffix text;
 20→  attempts int := 0;
 21→BEGIN
 22→  -- Get user email
 23→  raw_email := lower(trim(NEW.raw_user_meta_data->>'email'));
 24→  IF raw_email IS NULL OR raw_email = '' THEN
 25→    raw_email := lower(trim(NEW.email));
 26→  END IF;
 27→
 28→  -- Get inbound domain from config
 29→  SELECT inbound_email_domain INTO domain FROM public.platform_config LIMIT 1;
 30→  IF domain IS NULL OR domain = '' THEN
 31→    domain := 'inbound.rankora.co';
 32→  END IF;
 33→
 34→  -- Extract and sanitize local part (before @)
 35→  local_part := split_part(raw_email, '@', 1);
 36→  -- Replace any char that isn't alphanumeric, dot, or hyphen
 37→  local_part := regexp_replace(local_part, '[^a-z0-9.\-]', '.', 'g');
 38→  -- Collapse consecutive dots
 39→  local_part := regexp_replace(local_part, '\.{2,}', '.', 'g');
 40→  -- Trim leading/trailing dots
 41→  local_part := trim(both '.' from local_part);
 42→
 43→  IF local_part = '' THEN
 44→    local_part := 'user';
 45→  END IF;
 46→
 47→  base_inbox := local_part || '@' || domain;
 48→  final_inbox := base_inbox;
 49→
 50→  -- Check for collisions
 51→  WHILE EXISTS (SELECT 1 FROM public.profiles WHERE inbox_email = final_inbox) LOOP
 52→    attempts := attempts + 1;
 53→    suffix := substr(md5(random()::text), 1, 3);
 54→    final_inbox := local_part || '.' || suffix || '@' || domain;
 55→    IF attempts > 10 THEN
 56→      -- Fallback to full random
 57→      final_inbox := substr(md5(NEW.id::text || now()::text), 1, 12) || '@' || domain;
 58→      EXIT;
 59→    END IF;
 60→  END LOOP;
 61→
 62→  INSERT INTO public.profiles (user_id, credits, inbox_email)
 63→  VALUES (NEW.id, 5, final_inbox);
 64→
 65→  INSERT INTO public.user_roles (user_id, role)
 66→  VALUES (NEW.id, 'user');
 67→
 68→  RETURN NEW;
 69→END;
 70→$function$;
